pub(crate) fn available_pane_shell_from_job(child_pid: u32, job: ForegroundJob) -> Option<String> {
    if job.process_group_id != child_pid
        || job.processes.iter().any(|process| process.pid != child_pid)
    {
        return None;
    }
    job.processes
        .into_iter()
        .find(|process| process.pid == child_pid)
        .map(|process| process.name)
        .filter(|name| is_pane_shell_process_name(name))
}

pub(crate) fn available_pane_shell(child_pid: u32) -> Option<String> {
    super::available_pane_shell_from_job(child_pid, foreground_job(child_pid)?)
}

pub(super) fn handle_pane_process_info(
    &mut self,
    id: String,
    params: PaneProcessInfoParams,
) -> String {
    let Some((ws_idx, pane_id)) = self.resolve_optional_pane(params.pane_id.as_deref()) else {
        return encode_error(id, "pane_not_found", "pane not found");
    };
    let Some((runtime, _workspace_id)) = self.lookup_runtime(ws_idx, pane_id) else {
        return encode_error(id, "pane_not_found", "pane not found");
    };
    let Some(public_pane_id) = self.public_pane_id(ws_idx, pane_id) else {
        return encode_error(id, "pane_not_found", "pane not found");
    };
    let shell_pid = runtime.child_pid();
    let foreground_job = shell_pid.and_then(crate::detect::foreground_job);
    let foreground_process_group_id = foreground_job.as_ref().map(|job| job.process_group_id);
    let foreground_processes = foreground_job
        .map(|job| {
            job.processes
                .into_iter()
                .map(|process| PaneProcessInfoProcess {
                    pid: process.pid,
                    name: process.name,
                    argv0: process.argv0,
                    argv: process.argv,
                    cmdline: process.cmdline,
                    cwd: crate::platform::process_cwd(process.pid)
                        .map(|cwd| cwd.display().to_string()),
                })
                .collect()
        })
        .unwrap_or_default();

    encode_success(
        id,
        ResponseResult::PaneProcessInfo {
            process_info: PaneProcessInfo {
                pane_id: public_pane_id,
                shell_pid,
                foreground_process_group_id,
                tty: None,
                foreground_processes,
            },
        },
    )
}
